// Phase 3.2 background performance harness (outside the repo).
// Reuses the 3.1 approach: the REAL ChatInterface rendered through the profiling
// fixture, background applied via the production uiLayerOpacity helpers, measured
// with contentTracing + Performance.getMetrics + rAF frame timing.
//
// New in 3.2: measures the bounded GIF derivative against the native-resolution
// GIF, the Settings-preview amplifier, the modal-backdrop amplifier, and the two
// opacity paths. ORDER MATTERS: each unique media URL's first appearance gives a
// cold decode; every asset's "primary" scenario is listed first.
const { app, BrowserWindow, contentTracing } = require('electron');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const { pathToFileURL } = require('node:url');

const ROOT = '/home/mk_saadi/projects/persona-projects/llm-electron';
const AUDIT = '/tmp/opencode/bg32/harness';
const esbuild = require(path.join(ROOT, 'node_modules/esbuild'));

const WIDTH = Number(process.env.WIDTH || 1280);
const HEIGHT = Number(process.env.HEIGHT || 800);
const MS = Number(process.env.MS || 3000);
const ONLY = process.env.ONLY ? process.env.ONLY.split(',').map((s) => s.trim()) : null;

app.setPath('userData','/tmp/continuum-phase7/profile-background');
app.on('window-all-closed', () => {});

const stubDesktopChat = {
  name: 'stub-desktop-chat',
  setup(build) {
    build.onResolve({ filter: /desktopChat\.mjs$/ }, () => ({
      path: path.join(ROOT, 'tests/fixtures/desktopChatStub.mjs'),
    }));
  },
};

const CATS = [
  'devtools.timeline',
  'disabled-by-default-devtools.timeline',
  'disabled-by-default-devtools.timeline.frame',
  'toplevel',
  'benchmark',
  'viz',
  'cc',
];

const TARGETS = [
  'Paint', 'PaintImage', 'RasterTask', 'CompositeLayers', 'DrawFrame',
  'ActivateLayerTree', 'UpdateLayerTree', 'PrePaint', 'Layout', 'UpdateLayoutTree',
  'FunctionCall', 'ImageDecodeTask', 'GPUTask', 'MajorGC', 'MinorGC',
];

const media = (f) => pathToFileURL(path.join(AUDIT, f)).href;

async function readMetrics(webContents) {
  const { metrics } = await webContents.debugger.sendCommand('Performance.getMetrics');
  const map = {};
  for (const m of metrics) map[m.name] = m.value;
  return map;
}

const METRIC_KEYS = ['TaskDuration', 'ScriptDuration', 'LayoutDuration', 'RecalcStyleDuration', 'LayoutCount', 'RecalcStyleCount', 'JSHeapUsedSize'];

function metricDelta(before, after) {
  const out = {};
  for (const k of METRIC_KEYS) out[k] = +(((after[k] || 0) - (before[k] || 0))).toFixed(4);
  return out;
}

function summarizeTrace(trace) {
  const events = trace.traceEvents || trace;
  const sums = {};
  const counts = {};
  for (const ev of events) {
    if (ev.dur === undefined || !ev.name) continue;
    if (!TARGETS.includes(ev.name)) continue;
    sums[ev.name] = (sums[ev.name] || 0) + ev.dur;
    counts[ev.name] = (counts[ev.name] || 0) + 1;
  }
  const out = {};
  for (const name of TARGETS) out[name] = { ms: +(((sums[name] || 0) / 1000)).toFixed(2), count: counts[name] || 0 };
  return out;
}

function frameStats(frames) {
  if (!frames.length) return { frames: 0 };
  const sorted = [...frames].sort((a, b) => a - b);
  const pct = (p) => sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * p))];
  return {
    frames: frames.length,
    p50: +pct(0.5).toFixed(1),
    p95: +pct(0.95).toFixed(1),
    max: +Math.max(...frames).toFixed(1),
    over50ms: frames.filter((d) => d > 50).length,
    over100ms: frames.filter((d) => d > 100).length,
    avg: +(frames.reduce((a, b) => a + b, 0) / frames.length).toFixed(1),
  };
}

app.whenReady().then(async () => {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'bg32-'));
  const win = new BrowserWindow({
    width: WIDTH, height: HEIGHT, show: true,
    webPreferences: { sandbox: true, backgroundThrottling: false },
  });
  const results = [];
  try {
    await esbuild.build({
      entryPoints: [path.join(AUDIT, 'fixture32.jsx')],
      bundle: true,
      outfile: path.join(dir, 'fixture.js'),
      define: { 'process.env.NODE_ENV': '"production"' },
      absWorkingDir: ROOT,
      nodePaths: [path.join(ROOT, 'node_modules')],
      plugins: [stubDesktopChat],
    });
    const assets = path.join(ROOT, 'dist/assets');
    const css = (await fs.readdir(assets)).find((n) => n.endsWith('.css'));
    await fs.writeFile(
      path.join(dir, 'index.html'),
      `<html><head><link rel="stylesheet" href="${pathToFileURL(path.join(assets, css)).href}"><style>html,body,#root{height:100%;margin:0}</style></head><body><div id="root"></div><script src="fixture.js"></script></body></html>`,
    );
    await win.loadFile(path.join(dir, 'index.html'));
    win.webContents.debugger.attach('1.3');
    await win.webContents.debugger.sendCommand('Performance.enable');

    const renderApp = () => win.webContents.executeJavaScript(`(async () => {
      window.__render({ count: 200 });
      await new Promise((r) => setTimeout(r, 700));
      return true;
    })()`);

    const reset = () => win.webContents.executeJavaScript(`(() => {
      window.__applyBg('', 1);
      window.__dialog(false);
      window.__preview(null);
      const w = document.getElementById('audit-overlay'); if (w) w.remove();
      window.__applyBg('', 1);
      return true;
    })()`);

    const setHtmlBg = (url, opacity, animated) => win.webContents.executeJavaScript(
      `window.__applyBg(${JSON.stringify(url)}, ${opacity}, ${animated ? 'true' : 'false'})`,
    );

    const waitImage = (url) => win.webContents.executeJavaScript(`(async () => {
      await new Promise((res, rej) => { const i = new Image(); i.onload = res; i.onerror = rej; i.src = ${JSON.stringify(url)}; });
      return true;
    })()`);

    const sample = (scroll) => win.webContents.executeJavaScript(`(async () => {
      const scroller = window.__scroller();
      const frames = [];
      let last = performance.now();
      const start = last;
      const range = Math.max(200, scroller.scrollHeight - scroller.clientHeight);
      let dir = 1, pos = 0;
      return await new Promise((resolve) => {
        const loop = () => {
          const now = performance.now();
          frames.push(now - last);
          last = now;
          if (${scroll ? 'true' : 'false'}) {
            pos += 24 * dir;
            if (pos > range) { pos = range; dir = -1; }
            if (pos < 0) { pos = 0; dir = 1; }
            scroller.scrollTop = pos;
          }
          if (now - start < ${MS}) requestAnimationFrame(loop);
          else resolve(frames);
        };
        requestAnimationFrame(loop);
      });
    })()`);

    async function scenario(name, opts) {
      if (ONLY && !ONLY.includes(name)) return;
      const { file = null, opacity = 85, scroll = false, dialog = null, preview = null, churn = null, animated = false, trace = true } = opts;
      await reset();
      await renderApp();
      let url = file ? media(file) : '';
      if (file) { await waitImage(url); await setHtmlBg(url, opacity / 100, animated); }
      // dialog: 'blur' = production rule, 'noblur' = same dialog with the backdrop
      // filter neutralised, to separate "a modal exists" from "the blur costs".
      await win.webContents.executeJavaScript(`window.__setBackdropFilter(${JSON.stringify(dialog === 'noblur' ? 'none' : null)})`);
      if (dialog) await win.webContents.executeJavaScript('window.__dialog(true)');
      if (preview) await win.webContents.executeJavaScript(`window.__preview(${JSON.stringify(media(preview))})`);
      await new Promise((r) => setTimeout(r, 300));

      const before = await readMetrics(win.webContents);
      const renderBefore = await win.webContents.executeJavaScript('window.__renderCount');
      if (trace) {
        try {
          await contentTracing.startRecording({ included_categories: CATS, excluded_categories: [] });
        } catch {
          await contentTracing.startRecording({ categoryFilter: CATS.join(',') });
        }
      }
      if (churn) {
        await win.webContents.executeJavaScript(`window.__opacityChurn(${JSON.stringify(churn)}, ${JSON.stringify(url)}, ${MS - 200})`);
      }
      const frames = await sample(scroll);
      let paint = null;
      if (trace) {
        const tracePath = path.join(dir, 'trace-' + name + '.json');
        const res = await contentTracing.stopRecording(tracePath);
        let raw;
        if (typeof res === 'string') raw = await fs.readFile(res === '' ? tracePath : res, 'utf8');
        else if (Buffer.isBuffer(res)) raw = res.toString('utf8');
        else raw = await fs.readFile(tracePath, 'utf8');
        paint = summarizeTrace(JSON.parse(raw));
      }
      const after = await readMetrics(win.webContents);
      const renderAfter = await win.webContents.executeJavaScript('window.__renderCount');
      results.push({
        name, file, opacity, scroll, dialog, preview, churn,
        frames: frameStats(frames),
        metrics: metricDelta(before, after),
        reactRenders: renderAfter - renderBefore,
        paint,
      });
      console.log('done:', name);
    }

    const G3840 = 'gif_3840x2160_12f.gif';
    const G3840B = 'gif_3840x2160_12f.bounded.gif';
    const G1920 = 'gif_1920x1080_24f.gif';
    const G1280 = 'gif_1280x720_20f.gif';
    const POSTER = 'gif_3840x2160_12f.poster.png';

    for(let rep=0;rep<2;rep++) {
    await scenario('none-'+rep, {});
    await scenario('static-4k-'+rep, {file:'static_3840x2160.png'});
    await scenario('gif-normal-'+rep, {file:G1280,animated:true});
    await scenario('gif-bounded-'+rep, {file:G3840B,animated:true});
    await scenario('scroll-bounded-'+rep, {file:G3840B,animated:true,scroll:true});
    await scenario('modal-bounded-'+rep, {file:G3840B,animated:true,dialog:'blur',preview:POSTER});
    await scenario('opacity-bounded-'+rep, {file:G3840B,animated:true,churn:'only'});
    }
    let gpu = null;
    try {
      gpu = {
